/* AddressBook example: plain C structs -> wire bytes -> plain C structs.
 *
 * Application code only touches the structs in gen/addressbook.h
 * (generated by protoc-gen-pbwire-c from examples/addressbook.proto,
 * pinned here): struct literals in, layout tables and thin wrappers around
 * the generic struct engine in ../runtime/pbw_struct.h underneath.
 *
 * The schema loads once from its FileDescriptorSet
 * (examples/addressbook.desc) and covers every message in the file, so
 * there is no per-message setup: assign structs, encode, decode, compare.
 *
 * Build and run: `make examples` (from the repo root).
 */
#include <stdio.h>
#include <string.h>

#include "gen/addressbook.h"
#include "pbwire.h"

/* Field-by-field equality: decode must recover exactly what was encoded. */
static int
person_equal(const tutorial_person_t *a, const tutorial_person_t *b)
{
    size_t i;

    if (strcmp(a->name, b->name) != 0 || a->id != b->id) {
        return 0;
    }
    if ((a->email == NULL) != (b->email == NULL)) {
        return 0;
    }
    if (a->email != NULL && strcmp(a->email, b->email) != 0) {
        return 0;
    }
    if (a->n_phones != b->n_phones) {
        return 0;
    }
    for (i = 0; i < a->n_phones; i++) {
        if (strcmp(a->phones[i].number, b->phones[i].number) != 0 ||
            a->phones[i].type != b->phones[i].type ||
            a->phones[i].has_type != b->phones[i].has_type) {
            return 0;
        }
    }
    return 1;
}

static int
book_equal(const tutorial_address_book_t *a, const tutorial_address_book_t *b)
{
    size_t i;

    if (a->n_people != b->n_people) {
        return 0;
    }
    for (i = 0; i < a->n_people; i++) {
        if (!person_equal(&a->people[i], &b->people[i])) {
            return 0;
        }
    }
    return 1;
}

int
main(void)
{
    /* The whole demo input is struct literals; encode borrows them. */
    tutorial_person_phone_number_t alice_phones[] = {
        {
            .number = "555-0100",
            .type = TUTORIAL_PERSON_PHONE_TYPE_MOBILE,
            .has_type = 1,
        },
    };
    tutorial_person_phone_number_t bob_phones[] = {
        {
            .number = "555-0200",
            .type = TUTORIAL_PERSON_PHONE_TYPE_HOME,
            .has_type = 1,
        },
    };
    tutorial_person_t people[] = {
        {
            .name = "Alice",
            .id = 1,
            .email = NULL, /* absent stays absent */
            .phones = alice_phones,
            .n_phones = 1,
        },
        {
            .name = "Bob",
            .id = 2,
            .email = "bob@example.com",
            .phones = bob_phones,
            .n_phones = 1,
        },
    };
    tutorial_address_book_t book = {.people = people, .n_people = 2};
    tutorial_address_book_t got;
    pbw_schema *schema = NULL;
    uint8_t *wire = NULL;
    size_t wire_len = 0;
    int ok;

    /* One call loads every message in the .proto; no per-message setup. */
    if (pbw_struct_schema_load(ADDRESSBOOK_DESC_PATH, &schema) != PBW_OK) {
        fprintf(stderr, "load schema failed: %s\n", ADDRESSBOOK_DESC_PATH);
        return 1;
    }
    if (tutorial_address_book_encode(schema, &book, &wire, &wire_len) !=
        PBW_OK) {
        fprintf(stderr, "encode failed\n");
        pbw_schema_free(schema);
        return 1;
    }
    if (tutorial_address_book_decode(schema, wire, wire_len, &got) != PBW_OK) {
        fprintf(stderr, "decode failed\n");
        pbw_free(wire);
        pbw_schema_free(schema);
        return 1;
    }

    ok = book_equal(&book, &got);

    tutorial_address_book_free(&got);
    pbw_free(wire);
    pbw_schema_free(schema);
    return ok ? 0 : 1;
}
